<template>
    <div>
        <Head title="Divu faktoru autentifikācija" />
        <div class="row justify-content-center">
            <div class="lg:col-4 md:col-6 sm:col-8 ms-auto me-auto">
                <div class="card">
                    <div class="card-header card-header-primary text-center">
                        <h1 class="card-title h4">{{ recoveryMode ? 'Atkopšanas kods' : 'Autentifikatora kods' }}</h1>
                    </div>
                    <form @submit.prevent="submit">
                        <div class="card-body">
                            <p>{{ recoveryMode ? 'Ievadiet vienu no saglabātajiem atkopšanas kodiem. Katru kodu var izmantot tikai vienu reizi.' : 'Ievadiet sešciparu kodu no autentifikatora lietotnes.' }}</p>
                            <div class="form-group">
                                <template v-if="recoveryMode">
                                    <label for="challenge-recovery">Atkopšanas kods</label>
                                    <input id="challenge-recovery" key="recovery" ref="challengeInput" v-model="form.recovery_code" class="form-control" type="text" autocomplete="off" autocapitalize="none" spellcheck="false" required autofocus :disabled="form.processing">
                                </template>
                                <template v-else>
                                    <label for="challenge-code">Sešciparu kods</label>
                                    <input id="challenge-code" key="code" ref="challengeInput" v-model="form.code" class="form-control" type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required autofocus :disabled="form.processing">
                                </template>
                                <InputError :message="form.errors.code || form.errors.recovery_code" />
                            </div>
                        </div>
                        <div class="card-footer justify-content-center">
                            <button type="submit" class="btn btn-primary" :disabled="form.processing">{{ form.processing ? 'Pārbauda…' : 'Turpināt' }}</button>
                        </div>
                    </form>
                    <div class="text-center mb-3">
                        <button type="button" class="btn btn-link" :disabled="form.processing" @click="toggleMode">{{ recoveryMode ? 'Izmantot autentifikatora kodu' : 'Izmantot atkopšanas kodu' }}</button>
                        <p class="mb-0"><Link :href="loginUrl">Atgriezties pie pieteikšanās</Link></p>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { Head, Link, useForm } from '@inertiajs/vue3';
import InputError from '@scaffold/components/InputError.vue';
import { login } from '@app/routes';
import { store } from '@app/routes/two-factor/login';

export default {
    name: 'TwoFactorChallenge',
    components: { Head, InputError, Link },
    data() {
        return { recoveryMode: false, form: useForm({ code: '', recovery_code: '' }), loginUrl: login.url() };
    },
    methods: {
        submit() {
            this.form.transform(data => this.recoveryMode ? { recovery_code: data.recovery_code.trim() } : { code: data.code.trim() })
                .post(store.url(), { onFinish: () => this.form.reset('code', 'recovery_code') });
        },
        async toggleMode() {
            this.recoveryMode = !this.recoveryMode;
            this.form.resetAndClearErrors();
            await this.$nextTick();
            this.$refs.challengeInput?.focus();
        },
    },
};
</script>
